 "int.kind.pagerduty": "PagerDuty",
 "int.kind.pagerduty.d": "Avisa a quien esté de guardia.",
 "int.kind.radio": "Pasarela de radio / despacho",
 "int.kind.radio.d": "RoIP, puentes LMR, CAD — cualquier cosa con interfaz HTTP. Bidireccional.",
